    sid=st['step_id']
    if not st.get('tool_calls'):
        sig=('no tool', st.get('message','')[:50])
    else:
        tc=st['tool_calls'][0]
        args=tc.get('arguments',{})
        cmd=args.get('command','')
        # normalize call signature
        if tc['function_name']=='exec' and 'json/execute' in cmd:
            sig=('exec','POST /json/execute Page.navigate')
        elif tc['function_name']=='exec' and 'node-fetch' in cmd:
            sig=('exec','node-fetch')
        else:
            sig=(tc['function_name'], str(args)[:160])
    if sig!=prev:
        if prev is not None:
            print(f"steps {start}-{sid-1} x{count}: {prev}")
        prev=sig; start=sid; count=1
    else:
        count+=1
print(f"steps {start}-{traj['steps'][-1]['step_id']} x{count}: {prev}")
